  (SELECT COUNT(*) FROM el_mng_report_audit WHERE report_id IN (SELECT id FROM el_mng_report_revision WHERE exam_id IN ('9051103000000000501','9051103000000000502')))=2 AND
  (SELECT COUNT(*) FROM el_mng_report_reissue WHERE exam_id IN ('9051103000000000501','9051103000000000502'))=2 AND
  (SELECT COUNT(*) FROM el_mng_reissue_audit WHERE report_id IN (SELECT id FROM el_mng_report_reissue WHERE exam_id IN ('9051103000000000501','9051103000000000502')))=12 AND
  (SELECT COUNT(*) FROM el_mng_exam_draft WHERE exam_id IN ('9051103000000000501','9051103000000000502'))=0
